{"cards": [{"node_code": "N_dab39aed168673f9", "definition": "港务局及各类港务管理机构的组织架构、职能分工、人员编制、行政隶属关系及机构运行规范，聚焦于港口行政与技术管理的主体实体。", "boundary": "本节点聚焦于“机构”本身，即谁在管理。边界在于区分“机构实体”与“规章制度”（具体条文归入港章、条例）、“具体业务操作”（调度、装卸归入相应业务节点）。若内容涉及机构的历史沿革、改革方案或职能调整，归入本节点；若涉及机构内部的具体技术操作流程，需视侧重归入相应技术管理节点。", "includes": ["港务局、港口集团等管理机构的设立、撤销与合并", "港务管理机构的职能划分、部门设置及岗位职责", "港务管理机构的行政隶属关系、人事管理及组织变革"], "excludes": ["港口具体的调度指令、装卸工艺或设备维护操作细节", "港口行政监管的具体执法过程或海关、检疫业务操作", "港口基础设施的工程设计、施工或结构安全"], "sibling_distinctions": [{"other_code": "N_ccb05b0a566b6760", "rule": "本节点侧重“人”与“组织”（机构实体、架构、职能）；兄弟节点侧重“法”与“规”（具体的规章制度、条例文本）。"}, {"other_code": "N_d97c2c5133194ae3", "rule": "本节点侧重管理机构的整体架构与行政职能；兄弟节点侧重具体的“调度”业务环节及其配套设备。"}], "cross_boundary_rule": "若内容涉及机构改革的方案与实施，主挂载本节点；若涉及改革后新机构的具体调度流程，主挂载港口调度管理。"}, {"node_code": "N_ccb05b0a566b6760", "definition": "港口运营与管理中适用的章程、条例、规则、标准及规范性文件，涵盖港口行政、作业、安全、环保等方面的制度规定。", "boundary": "本节点聚焦于“制度文本”与“规范依据”。边界在于区分“制度规定”与“机构实体”（归入港务局及港务管理机构）、“具体执行”（归入调度、装卸等节点）。若内容是对某条法规的解读、适用案例分析或法规汇编，归入本节点；若涉及法规制定过程中的政治博弈或宏观政策背景，需视侧重，侧重技术执行规范归本节点。", "includes": ["港口章程、港口条例、港口作业规则等规范性文件", "港口安全管理、环境保护、劳动保护等方面的技术标准与规定", "国际港口公约、协定及国内港口法规的汇编与解读"], "excludes": ["港务管理机构的组织架构、人员编制或行政隶属关系", "港口调度、装卸、设备维护等具体技术操作流程", "港口基础设施的工程设计、施工规范或结构标准"], "sibling_distinctions": [{"other_code": "N_dab39aed168673f9", "rule": "本节点侧重“规则”（条文、标准、规范）；兄弟节点侧重“组织”（机构、部门、职能）。"}, {"other_code": "N_4b76a429d2dbe5e7", "rule": "本节点侧重港口内部或通用的作业、安全、管理规章；兄弟节点侧重海关、检疫、边防等特定行政监管领域的具体管理工作。"}], "cross_boundary_rule": "若内容涉及法规的制定与修订过程，主挂载本节点；若涉及法规在具体调度或装卸业务中的应用，主挂载相应业务节点。"}, {"node_code": "N_d97c2c5133194ae3", "definition": "港口生产作业中的调度指挥体系、调度流程、调度方法，以及用于调度指挥的通信、监控、信息处理等专用设备的配置与管理。", "boundary": "本节点聚焦于“调度”这一核心业务环节及其技术支撑。边界在于区分“调度业务”与“机构管理”（归入港务局及港务管理机构）、“装卸作业”（归入水运货物传送、装卸技术与设备）。若内容涉及调度算法、调度系统软件、调度通信设备，归入本节点；若涉及调度人员的行政考核或机构编制，归入港务局及港务管理机构。", "includes": ["港口船舶、货物、设备的调度计划、指挥流程及协调机制", "港口调度通信系统、监控设备、信息处理系统的配置与维护", "调度作业的效率评估、调度规则及调度人员的技术操作规范"], "excludes": ["港务管理机构的整体架构、职能划分或行政隶属关系", "港口装卸机械的具体操作工艺、传送带设计或自动化控制算法", "港口基础设施的工程设计、施工或结构安全"], "sibling_distinctions": [{"other_code": "N_dab39aed168673f9", "rule": "本节点侧重“调度”这一具体业务环节及其技术设备；兄弟节点侧重管理机构的整体架构与行政职能。"}, {"other_code": "N_7cdaa494e5ff0df2", "rule": "本节点侧重调度指挥系统（通信、监控、信息）；兄弟节点侧重港口生产机械（起重机、输送机等）及电气设备的维护管理。"}], "cross_boundary_rule": "若内容涉及调度系统的整体架构与管理流程，主挂载本节点；若仅涉及调度通信设备的具体硬件维护，可关联港口机械及电气设备的管理。"}]}
